1	import { Router, type IRouter } from "express";
2	import { and, asc, eq, gte, inArray, lte, ne, or } from "drizzle-orm";
3	import { z } from "zod";
4	import {
5	  db,
6	  coachesTable,
7	  coachAvailabilitiesTable,
8	  coachBlockedSlotsTable,
9	  coachSportsTable,
10	  courtCoachesTable,
11	  courtsTable,
12	  userProfilesTable,
13	  bookingsTable,
14	  coachServicesTable,
15	  facilitiesTable,
16	} from "@workspace/db";
17	import { requireAuth, requireCoach, getCurrentUserId, resolveCoachUserId } from "../lib/auth";
18	import { getCoachAvailability, vilniusToUtc } from "../lib/coach-availability";
19	
20	const router: IRouter = Router();
21	
22	// ─── Schemas ─────────────────────────────────────────────────────────────────
23	
24	const HHMM = /^([01]\d|2[0-3]):[0-5]\d$/;
25	
26	const AvailabilityEntrySchema = z.object({
27	  dayOfWeek: z.coerce.number().int().min(0).max(6),
28	  startTime: z.string().regex(HHMM, "Time must be HH:MM"),
29	  endTime: z.string().regex(HHMM, "Time must be HH:MM"),
30	}).refine((e) => e.startTime < e.endTime, {
31	  message: "endTime must be after startTime",
32	  path: ["endTime"],
33	});
34	
35	const AvailabilityReplaceBody = z.object({
36	  entries: z.array(AvailabilityEntrySchema),
37	});
38	
39	const BlockedSlotCreateBody = z.object({
40	  startTime: z.string().datetime({ offset: true }),
41	  endTime: z.string().datetime({ offset: true }),
42	  reason: z.string().max(280).optional().nullable(),
43	}).refine((b) => new Date(b.startTime) < new Date(b.endTime), {
44	  message: "endTime must be after startTime",
45	  path: ["endTime"],
46	});
47	
48	// ─── Helpers ─────────────────────────────────────────────────────────────────
49	
50	async function getMyCoachId(userId: string): Promise<number | null> {
51	  const [coach] = await db
52	    .select({ id: coachesTable.id })
53	    .from(coachesTable)
54	    .where(eq(coachesTable.userId, userId));
55	  return coach?.id ?? null;
56	}
57	
58	async function getCoachOwnerUserId(coachId: number): Promise<string | null> {
59	  const [c] = await db
60	    .select({ userId: coachesTable.userId })
61	    .from(coachesTable)
62	    .where(eq(coachesTable.id, coachId));
63	  return c?.userId ?? null;
64	}
65	
66	// ─── Weekly availability ─────────────────────────────────────────────────────
67	
68	// GET /coaches/me/availability — coach's own weekly schedule
69	router.get("/coaches/me/availability", requireCoach, async (req, res): Promise<void> => {
70	  const userId = (await resolveCoachUserId(req))!;
71	  const coachId = await getMyCoachId(userId);
72	  if (coachId == null) { res.json([]); return; }
73	
74	  const rows = await db
75	    .select()
76	    .from(coachAvailabilitiesTable)
77	    .where(eq(coachAvailabilitiesTable.coachId, coachId))
78	    .orderBy(asc(coachAvailabilitiesTable.dayOfWeek), asc(coachAvailabilitiesTable.startTime));
79	
80	  res.json(rows.map((r) => ({
81	    id: r.id,
82	    dayOfWeek: r.dayOfWeek,
83	    startTime: r.startTime,
84	    endTime: r.endTime,
85	  })));
86	});
87	
88	// PUT /coaches/me/availability — replace the full weekly schedule atomically
89	router.put("/coaches/me/availability", requireCoach, async (req, res): Promise<void> => {
90	  const userId = getCurrentUserId(req)!;
91	  const coachId = await getMyCoachId(userId);
92	  if (coachId == null) { res.status(400).json({ error: "Create your coach profile first" }); return; }
93	
94	  const parsed = AvailabilityReplaceBody.safeParse(req.body);
95	  if (!parsed.success) {
96	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
97	    return;
98	  }
99	
100	  // Replace-all semantics: delete existing rows and re-insert the new set.
101	  // Cheap because the per-coach row count is tiny (typically <30).
102	  await db.transaction(async (tx) => {
103	    await tx.delete(coachAvailabilitiesTable).where(eq(coachAvailabilitiesTable.coachId, coachId));
104	    if (parsed.data.entries.length > 0) {
105	      await tx.insert(coachAvailabilitiesTable).values(
106	        parsed.data.entries.map((e) => ({
107	          coachId,
108	          dayOfWeek: e.dayOfWeek,
109	          startTime: e.startTime,
110	          endTime: e.endTime,
111	        })),
112	      );
113	    }
114	  });
115	
116	  const rows = await db
117	    .select()
118	    .from(coachAvailabilitiesTable)
119	    .where(eq(coachAvailabilitiesTable.coachId, coachId))
120	    .orderBy(asc(coachAvailabilitiesTable.dayOfWeek), asc(coachAvailabilitiesTable.startTime));
121	
122	  res.json(rows.map((r) => ({
123	    id: r.id,
124	    dayOfWeek: r.dayOfWeek,
125	    startTime: r.startTime,
126	    endTime: r.endTime,
127	  })));
128	});
129	
130	// ─── Blocked slots ───────────────────────────────────────────────────────────
131	
132	// GET /coaches/me/blocked-slots?from=ISO&to=ISO
133	router.get("/coaches/me/blocked-slots", requireCoach, async (req, res): Promise<void> => {
134	  const userId = (await resolveCoachUserId(req))!;
135	  const coachId = await getMyCoachId(userId);
136	  if (coachId == null) { res.json([]); return; }
137	
138	  // Default window: today (UTC) through +180 days, so the UI gets the
139	  // upcoming-blocks view without having to specify a range.
140	  const from = req.query.from ? new Date(String(req.query.from)) : new Date();
141	  const to = req.query.to
142	    ? new Date(String(req.query.to))
143	    : new Date(from.getTime() + 180 * 24 * 3600 * 1000);
144	
145	  const rows = await db
146	    .select()
147	    .from(coachBlockedSlotsTable)
148	    .where(and(
149	      eq(coachBlockedSlotsTable.coachId, coachId),
150	      gte(coachBlockedSlotsTable.endTime, from),
151	      lte(coachBlockedSlotsTable.startTime, to),
152	    ))
153	    .orderBy(asc(coachBlockedSlotsTable.startTime));
154	
155	  res.json(rows.map((r) => ({
156	    id: r.id,
157	    startTime: r.startTime.toISOString(),
158	    endTime: r.endTime.toISOString(),
159	    reason: r.reason,
160	  })));
161	});
162	
163	// POST /coaches/me/blocked-slots
164	router.post("/coaches/me/blocked-slots", requireCoach, async (req, res): Promise<void> => {
165	  const userId = getCurrentUserId(req)!;
166	  const coachId = await getMyCoachId(userId);
167	  if (coachId == null) { res.status(400).json({ error: "Create your coach profile first" }); return; }
168	
169	  const parsed = BlockedSlotCreateBody.safeParse(req.body);
170	  if (!parsed.success) {
171	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
172	    return;
173	  }
174	
175	  const [row] = await db.insert(coachBlockedSlotsTable).values({
176	    coachId,
177	    startTime: new Date(parsed.data.startTime),
178	    endTime: new Date(parsed.data.endTime),
179	    reason: parsed.data.reason ?? null,
180	  }).returning();
181	
182	  res.status(201).json({
183	    id: row.id,
184	    startTime: row.startTime.toISOString(),
185	    endTime: row.endTime.toISOString(),
186	    reason: row.reason,
187	  });
188	});
189	
190	// DELETE /coaches/me/blocked-slots/:id
191	router.delete("/coaches/me/blocked-slots/:id", requireCoach, async (req, res): Promise<void> => {
192	  const userId = getCurrentUserId(req)!;
193	  const coachId = await getMyCoachId(userId);
194	  if (coachId == null) { res.status(404).json({ error: "Coach not found" }); return; }
195	
196	  const blockId = Number(req.params.id);
197	  if (!Number.isFinite(blockId)) { res.status(400).json({ error: "Invalid id" }); return; }
198	
199	  // Bind ownership server-side — never trust the path id alone.
200	  const deleted = await db.delete(coachBlockedSlotsTable)
201	    .where(and(
202	      eq(coachBlockedSlotsTable.id, blockId),
203	      eq(coachBlockedSlotsTable.coachId, coachId),
204	    ))
205	    .returning({ id: coachBlockedSlotsTable.id });
206	
207	  if (deleted.length === 0) { res.status(404).json({ error: "Block not found" }); return; }
208	  res.json({ ok: true });
209	});
210	
211	// ─── Unified schedule feed (dashboard calendar) ──────────────────────────────
212	
213	const ScheduleRangeQuery = z.object({
214	  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
215	  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
216	}).refine((q) => q.from <= q.to, { message: "from must be <= to" });
217	
218	const ManualBookingBody = z.object({
219	  courtId: z.number().int().positive(),
220	  customerName: z.string().trim().min(1).max(200),
221	  customerEmail: z.string().trim().email().max(200).optional().nullable(),
222	  customerPhone: z.string().trim().max(50).optional().nullable(),
223	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
224	  startTime: z.string().regex(HHMM),
225	  endTime: z.string().regex(HHMM),
226	  note: z.string().max(280).optional().nullable(),
227	}).refine((b) => b.startTime < b.endTime, {
228	  message: "endTime must be after startTime",
229	  path: ["endTime"],
230	});
231	
232	function daysBetween(fromYmd: string, toYmd: string): string[] {
233	  const start = new Date(`${fromYmd}T00:00:00Z`);
234	  const end = new Date(`${toYmd}T00:00:00Z`);
235	  const out: string[] = [];
236	  for (let d = start.getTime(); d <= end.getTime(); d += 86_400_000) {
237	    out.push(new Date(d).toISOString().slice(0, 10));
238	  }
239	  return out;
240	}
241	
242	// GET /coaches/me/schedule?from=YYYY-MM-DD&to=YYYY-MM-DD
243	//
244	// Returns everything the dashboard calendar needs in one round-trip:
245	// recurring weekly hours (so the UI can paint the working-hours envelope),
246	// one-off blocks in the range, and bookings attached to this coach with
247	// enough joined context (court name, service, booker) to render each cell.
248	//
249	// Range is capped at 14 days to keep the bookings join bounded. Defaults to
250	// today through +7 days if either bound is omitted.
251	router.get("/coaches/me/schedule", requireCoach, async (req, res): Promise<void> => {
