255	  const today = new Date().toISOString().slice(0, 10);
256	  const sevenAhead = new Date(Date.now() + 7 * 86_400_000).toISOString().slice(0, 10);
257	  const parsed = ScheduleRangeQuery.safeParse({
258	    from: String(req.query.from ?? today),
259	    to: String(req.query.to ?? sevenAhead),
260	  });
261	  if (!parsed.success) {
262	    res.status(400).json({ error: "Invalid range", details: parsed.error.flatten() });
263	    return;
264	  }
265	  const { from, to } = parsed.data;
266	  const range = daysBetween(from, to);
267	  if (range.length > 14) {
268	    res.status(400).json({ error: "Range must be <= 14 days" });
269	    return;
270	  }
271	
272	  // No coach record yet (e.g. admin without a coach row): still return a
273	  // well-formed envelope including `range` so the frontend's empty-state
274	  // rendering can rely on a consistent shape.
