313	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
314	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
315	      .leftJoin(coachServicesTable, eq(bookingsTable.coachServiceId, coachServicesTable.id))
316	      .where(and(
317	        eq(bookingsTable.coachId, userId),
318	        gte(bookingsTable.date, from),
