367	  const userId = getCurrentUserId(req)!;
368	  const coachId = await getMyCoachId(userId);
369	  if (coachId == null) {
370	    res.status(400).json({ error: "Create your coach profile first" });
371	    return;
372	  }
373	
374	  const parsed = ManualBookingBody.safeParse(req.body);
375	  if (!parsed.success) {
376	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
377	    return;
378	  }
379	  const { courtId, customerName, customerEmail, customerPhone, date, startTime, endTime, note } = parsed.data;
380	
381	  // Ownership check: coach must be approved at this court.
382	  const [affiliation] = await db
383	    .select({ courtId: courtCoachesTable.courtId })
384	    .from(courtCoachesTable)
385	    .where(and(
386	      eq(courtCoachesTable.coachId, coachId),
387	      eq(courtCoachesTable.courtId, courtId),
388	    ));
389	  if (!affiliation) {
390	    res.status(403).json({ error: "You are not affiliated with this court" });
391	    return;
392	  }
393	
394	  // Overlap check against this coach's other live bookings — same userId only,
395	  // since a court-level conflict is a separate concern owned by the court owner.
396	  const overlapping = await db
397	    .select({ id: bookingsTable.id })
398	    .from(bookingsTable)
399	    .where(and(
400	      eq(bookingsTable.coachId, userId),
401	      eq(bookingsTable.date, date),
402	      ne(bookingsTable.status, "cancelled"),
403	      // [existing.start, existing.end) ∩ [new.start, new.end) ≠ ∅ iff
404	      // existing.start < new.end AND new.start < existing.end.
405	      lte(bookingsTable.startTime, endTime),
406	      gte(bookingsTable.endTime, startTime),
407	    ));
408	  if (overlapping.length > 0) {
409	    res.status(409).json({ error: "Slot overlaps an existing booking" });
410	    return;
411	  }
