417	    customerEmail: customerEmail ?? "",
418	    customerPhone: customerPhone ?? null,
419	    date,
420	    startTime,
421	    endTime,
422	    totalPrice: "0",
423	    status: "confirmed",
424	    coachId: userId,
425	    notes: note ?? null,
426	  }).returning();
