460	// ─── Available coaches for a court+window ────────────────────────────────────
461	//
462	// GET /courts/:id/available-coaches?date=YYYY-MM-DD&startTime=HH:MM&endTime=HH:MM
463	//
464	// Returns the coaches a player can attach to a [startTime, endTime] booking
465	// at this court. A coach qualifies only if ALL of:
466	//   1. status='approved' and isAcceptingStudents=true
467	//   2. courtPaymentModel='student_pays_court'  (Strike 2 scope)
468	//   3. Their user_profile has stripeAccountStatus='active'
469	//   4. travelPolicy='any_court' OR they have an approved courtCoachesTable
470	//      row for this courtId
471	//   5. getCoachAvailability covers every 30-min slot in [startTime, endTime)
472	//      for the given Europe/Vilnius date
473	//
474	// The window MUST align to 30-minute boundaries (the slot granularity).
475	router.get("/courts/:id/available-coaches", requireAuth, async (req, res): Promise<void> => {
476	  const courtId = Number(req.params.id);
477	  if (!Number.isFinite(courtId)) { res.status(400).json({ error: "Invalid court id" }); return; }
478	
479	  const date = String(req.query.date ?? "");
480	  const startTime = String(req.query.startTime ?? "");
481	  const endTime = String(req.query.endTime ?? "");
482	
483	  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
484	    res.status(400).json({ error: "date must be YYYY-MM-DD" }); return;
485	  }
486	  if (!/^\d{2}:\d{2}$/.test(startTime) || !/^\d{2}:\d{2}$/.test(endTime)) {
487	    res.status(400).json({ error: "startTime/endTime must be HH:MM" }); return;
488	  }
489	
490	  const [court] = await db
491	    .select({ id: courtsTable.id, status: courtsTable.status })
492	    .from(courtsTable)
493	    .where(eq(courtsTable.id, courtId));
494	  if (!court || court.status !== "active") {
495	    res.status(404).json({ error: "Court not found" }); return;
496	  }
497	
498	  const requestStartUtc = vilniusToUtc(date, startTime).getTime();
499	  const requestEndUtc = vilniusToUtc(date, endTime).getTime();
500	  if (requestEndUtc <= requestStartUtc) {
501	    res.status(400).json({ error: "endTime must be after startTime" }); return;
502	  }
503	  const STEP_MS = 30 * 60_000;
504	  if ((requestEndUtc - requestStartUtc) % STEP_MS !== 0) {
505	    res.status(400).json({ error: "Window must align to 30-minute slots" }); return;
506	  }
507	
508	  // Static filter on coaches that could theoretically take this booking.
509	  const candidates = await db
510	    .select({
511	      id: coachesTable.id,
512	      userId: coachesTable.userId,
513	      name: coachesTable.name,
514	      photoUrl: coachesTable.photoUrl,
515	      pricePerHour: coachesTable.pricePerHour,
516	      travelPolicy: coachesTable.travelPolicy,
517	      cancellationPolicy: coachesTable.cancellationPolicy,
518	      sports: coachesTable.sports,
519	      experienceYears: coachesTable.experienceYears,
520	    })
521	    .from(coachesTable)
522	    .innerJoin(userProfilesTable, eq(coachesTable.userId, userProfilesTable.userId))
523	    .where(and(
524	      eq(coachesTable.status, "approved"),
525	      eq(coachesTable.isAcceptingStudents, true),
526	      eq(coachesTable.courtPaymentModel, "student_pays_court"),
527	      eq(userProfilesTable.stripeAccountStatus, "active"),
528	    ));
529	
530	  if (candidates.length === 0) { res.json({ coaches: [] }); return; }
531	
532	  // Travel-policy filter: any_court passes always; affiliated_only requires
533	  // an approved courtCoachesTable row for THIS court.
534	  const candidateIds = candidates.map((c) => c.id);
535	  const affiliations = await db
536	    .select({ coachId: courtCoachesTable.coachId })
537	    .from(courtCoachesTable)
538	    .where(and(
539	      eq(courtCoachesTable.courtId, courtId),
540	      inArray(courtCoachesTable.coachId, candidateIds),
541	    ));
542	  const affiliatedSet = new Set(affiliations.map((a) => a.coachId));
543	  const eligible = candidates.filter((c) =>
544	    c.travelPolicy === "any_court" || affiliatedSet.has(c.id),
545	  );
546	
547	  // Pre-load per-sport audiences for the eligible coach set in one query so
548	  // the picker can render audience pills. We don't filter on (sport, audience)
549	  // here — the picker is court-level; the player applies sport/audience
550	  // filters by visual inspection of the rendered tags.
551	  const eligibleIds = eligible.map((c) => c.id);
552	  const sportsRows = eligibleIds.length > 0
553	    ? await db.select({
554	        coachId: coachSportsTable.coachId,
555	        sport: coachSportsTable.sport,
556	        audiences: coachSportsTable.audiences,
557	      })
558	        .from(coachSportsTable)
559	        .where(inArray(coachSportsTable.coachId, eligibleIds))
560	    : [];
561	  const sportsByCoach = new Map<number, Array<{ sport: string; audiences: string[] }>>();
562	  for (const r of sportsRows) {
563	    if (!sportsByCoach.has(r.coachId)) sportsByCoach.set(r.coachId, []);
564	    sportsByCoach.get(r.coachId)!.push({ sport: r.sport, audiences: r.audiences });
565	  }
566	
567	  // Per-coach continuous-coverage check. Each getCoachAvailability call is
568	  // 2 small queries; we run them in parallel. Typical N is tiny (<20).
569	  const checks = await Promise.all(eligible.map(async (c) => {
570	    const slots = await getCoachAvailability(c.id, date);
571	    const slotMs = new Set(slots.map((s) => new Date(s.start).getTime()));
572	    for (let t = requestStartUtc; t < requestEndUtc; t += STEP_MS) {
573	      if (!slotMs.has(t)) return null;
574	    }
575	    return {
576	      id: c.id,
577	      name: c.name,
578	      photoUrl: c.photoUrl ?? null,
579	      pricePerHour: c.pricePerHour ?? null,
580	      sports: c.sports,
581	      experienceYears: c.experienceYears ?? null,
582	      cancellationPolicy: c.cancellationPolicy,
583	      sportsAudiences: sportsByCoach.get(c.id) ?? [],
584	    };
585	  }));
586	
587	  res.json({ coaches: checks.filter((c): c is NonNullable<typeof c> => c !== null) });
588	});
