27	// ─── Date helpers (Europe/Vilnius local) ────────────────────────────────────
28	//
29	// bookings.date is stored as `YYYY-MM-DD` in Vilnius local time and
30	// bookings.startTime/endTime as `HH:MM` in the same zone, so we can compute
31	// the week/month boundaries using local-date math without any UTC conversion.
32	// Lexicographic string comparison on YYYY-MM-DD matches chronological order.
33	
34	function ymd(d: Date): string {
35	  const y = d.getFullYear();
36	  const m = String(d.getMonth() + 1).padStart(2, "0");
37	  const day = String(d.getDate()).padStart(2, "0");
38	  return `${y}-${m}-${day}`;
39	}
40	
41	function currentWeekRange(now = new Date()): { from: string; to: string } {
42	  // ISO week boundaries: Monday → Sunday. JS getDay returns 0..6 with 0=Sun.
43	  const dow = now.getDay() || 7; // Sunday → 7 so Monday → -0 days
44	  const monday = new Date(now);
45	  monday.setHours(0, 0, 0, 0);
46	  monday.setDate(monday.getDate() - (dow - 1));
47	  const sunday = new Date(monday);
48	  sunday.setDate(monday.getDate() + 6);
49	  return { from: ymd(monday), to: ymd(sunday) };
50	}
51	
52	function currentMonthRange(now = new Date()): { from: string; to: string } {
53	  const first = new Date(now.getFullYear(), now.getMonth(), 1);
54	  const last = new Date(now.getFullYear(), now.getMonth() + 1, 0);
55	  return { from: ymd(first), to: ymd(last) };
56	}
57	
58	// "HH:MM" → minutes since midnight.
59	function hmToMin(hm: string): number {
60	  const [h, m] = hm.split(":").map(Number);
61	  return h * 60 + m;
62	}
63	
64	// Minutes between two HH:MM strings on the same date. Returns 0 for malformed
65	// input so a corrupt booking doesn't crash the aggregate.
66	function bookingDurationMin(start: string, end: string): number {
67	  const s = hmToMin(start);
68	  const e = hmToMin(end);
69	  if (!Number.isFinite(s) || !Number.isFinite(e) || e <= s) return 0;
70	  return e - s;
71	}
