73	// Chunked Clerk lookup. Mirrors the pattern in admin.ts so a failing chunk
74	// degrades gracefully (those rows just resolve to null name/email/imageUrl).
75	async function batchResolveClerkUsers(userIds: string[]): Promise<
76	  Record<string, { name: string | null; email: string | null; imageUrl: string | null }>
77	> {
78	  const result: Record<string, { name: string | null; email: string | null; imageUrl: string | null }> = {};
79	  const unique = Array.from(new Set(userIds.filter(Boolean)));
80	  const CHUNK = 100;
81	  for (let i = 0; i < unique.length; i += CHUNK) {
82	    const chunk = unique.slice(i, i + CHUNK);
83	    try {
84	      const resp = await clerkClient.users.getUserList({ userId: chunk, limit: CHUNK });
85	      for (const u of resp.data) {
86	        const name = [u.firstName, u.lastName].filter(Boolean).join(" ") || null;
87	        result[u.id] = {
88	          name,
89	          email: u.emailAddresses?.[0]?.emailAddress ?? null,
90	          imageUrl: u.imageUrl ?? null,
91	        };
92	      }
93	    } catch {
94	      // Skip failed chunks; consumers get null fields and the page still renders.
95	    }
96	  }
97	  return result;
98	}
