102	router.get("/coaches/me/dashboard-stats", requireCoach, async (req, res): Promise<void> => {
103	  const userId = (await resolveCoachUserId(req))!;
104	  const week = currentWeekRange();
105	  const month = currentMonthRange();
106	
107	  // KPIs are computed with three small grouped queries so we don't pull rows
108	  // into Node. The "upcoming" list is the only raw-row fetch — capped at 5.
109	  // Booking statuses we count: 'confirmed' and 'awaiting_players' for the
110	  // active funnel; we explicitly exclude 'cancelled' and 'blocked'.
111	  const ACTIVE_STATUSES = ["confirmed", "awaiting_players"] as const;
112	
113	  const [weekRow, distinctStudentsRow, monthDurationRows, upcomingRows] = await Promise.all([
114	    // Lessons this week — count of bookings within Mon..Sun in the active funnel.
115	    db.select({ count: sql<number>`COUNT(*)::int` })
116	      .from(bookingsTable)
117	      .where(and(
118	        eq(bookingsTable.coachId, userId),
119	        gte(bookingsTable.date, week.from),
120	        lte(bookingsTable.date, week.to),
121	        inArray(bookingsTable.status, ACTIVE_STATUSES as unknown as string[]),
122	      )),
123	
124	    // Active students all-time. Confirmed bookings only; treat each unique
125	    // bookerUserId as one student, plus distinct customerEmail for the guest
126	    // tail (bookerUserId IS NULL).
127	    db.select({
128	      count: sql<number>`
129	        COUNT(DISTINCT COALESCE(${bookingsTable.bookerUserId}, ${bookingsTable.customerEmail}))::int
130	      `,
131	    })
132	      .from(bookingsTable)
133	      .where(and(
134	        eq(bookingsTable.coachId, userId),
135	        eq(bookingsTable.status, "confirmed"),
136	      )),
137	
138	    // Total lesson minutes this month. We sum (endTime - startTime) in
139	    // application code — Postgres has no built-in HH:MM diff and casting to
140	    // interval/timestamp would obscure the simple math.
141	    db.select({
142	      startTime: bookingsTable.startTime,
143	      endTime: bookingsTable.endTime,
144	    })
145	      .from(bookingsTable)
146	      .where(and(
147	        eq(bookingsTable.coachId, userId),
148	        gte(bookingsTable.date, month.from),
149	        lte(bookingsTable.date, month.to),
150	        inArray(bookingsTable.status, ACTIVE_STATUSES as unknown as string[]),
151	      )),
152	
153	    // Upcoming bookings — date >= today, confirmed funnel, ordered by date+start.
154	    db.select({
155	      booking: bookingsTable,
156	      courtName: courtsTable.name,
157	      facilityName: facilitiesTable.name,
158	      serviceName: coachServicesTable.name,
159	    })
160	      .from(bookingsTable)
161	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
162	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
163	      .leftJoin(coachServicesTable, eq(bookingsTable.coachServiceId, coachServicesTable.id))
164	      .where(and(
165	        eq(bookingsTable.coachId, userId),
166	        gte(bookingsTable.date, ymd(new Date())),
167	        inArray(bookingsTable.status, ACTIVE_STATUSES as unknown as string[]),
168	      ))
169	      .orderBy(asc(bookingsTable.date), asc(bookingsTable.startTime))
170	      .limit(5),
171	  ]);
172	
173	  const totalMinutesThisMonth = monthDurationRows.reduce(
174	    (acc, r) => acc + bookingDurationMin(r.startTime, r.endTime),
175	    0,
176	  );
177	
178	  res.json({
179	    lessonsThisWeek: weekRow[0]?.count ?? 0,
180	    activeStudents: distinctStudentsRow[0]?.count ?? 0,
181	    totalMinutesThisMonth,
182	    week: { from: week.from, to: week.to },
183	    upcomingBookings: upcomingRows.map((r) => ({
184	      id: r.booking.id,
185	      date: r.booking.date,
186	      startTime: r.booking.startTime,
187	      endTime: r.booking.endTime,
188	      status: r.booking.status,
189	      courtId: r.booking.courtId,
190	      courtName: r.courtName,
191	      facilityName: r.facilityName,
192	      serviceName: r.serviceName,
193	      customerName: r.booking.customerName,
194	      // Manual = guest-style booking the coach created off-platform.
195	      isManual: r.booking.bookerUserId === null && Number(r.booking.totalPrice) === 0,
196	    })),
197	  });
198	});
