247	// ─── GET /coaches/me/bookings ───────────────────────────────────────────────
248	
249	const ListBookingsQuery = z.object({
250	  scope: z.enum(["all", "upcoming", "past"]).default("all"),
251	  status: z.enum(["all", "confirmed", "awaiting_players", "pending", "cancelled"]).default("all"),
252	  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
253	  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
254	  search: z.string().trim().min(1).max(120).optional(),
255	  sort: z.enum(["date", "price"]).default("date"),
256	  order: z.enum(["asc", "desc"]).optional(),
257	  limit: z.coerce.number().int().min(1).max(100).default(20),
258	  offset: z.coerce.number().int().min(0).default(0),
259	});
260	
261	router.get("/coaches/me/bookings", requireCoach, async (req, res): Promise<void> => {
262	  const parsed = ListBookingsQuery.safeParse(req.query);
263	  if (!parsed.success) {
264	    res.status(400).json({ error: "invalid_query", details: parsed.error.flatten() });
265	    return;
266	  }
267	  const q = parsed.data;
268	  const userId = (await resolveCoachUserId(req))!;
269	  const today = ymd(new Date());
270	
271	  // Build the predicate. We always scope to the coach's bookings, and we
272	  // never include the `blocked` synthetic status (those are owner-side
273	  // court blocks, not coach lessons even though they share the table).
274	  const filters = [eq(bookingsTable.coachId, userId), ne(bookingsTable.status, "blocked")];
275	
276	  if (q.scope === "upcoming") {
277	    filters.push(gte(bookingsTable.date, today));
278	  } else if (q.scope === "past") {
279	    filters.push(lt(bookingsTable.date, today));
280	  }
281	
282	  if (q.status !== "all") {
283	    filters.push(eq(bookingsTable.status, q.status));
284	  }
285	
286	  if (q.from) filters.push(gte(bookingsTable.date, q.from));
287	  if (q.to) filters.push(lte(bookingsTable.date, q.to));
288	
289	  if (q.search) {
290	    const pattern = `%${q.search}%`;
291	    // Pre-coalesce phone NULL → '' so ilike doesn't drop rows with no phone.
292	    filters.push(
293	      or(
294	        ilike(bookingsTable.customerName, pattern),
295	        ilike(bookingsTable.customerEmail, pattern),
296	        ilike(sql<string>`COALESCE(${bookingsTable.customerPhone}, '')`, pattern),
297	      )!,
298	    );
299	  }
300	
301	  // Sort: for upcoming, default ascending (nearest first); past defaults to
302	  // descending (most recent first); explicit `order` always wins.
303	  const dir = q.order
304	    ? (q.order === "asc" ? asc : desc)
305	    : (q.scope === "past" ? desc : asc);
306	
307	  const orderByColumns = q.sort === "price"
308	    ? [dir(bookingsTable.totalPrice), dir(bookingsTable.date), dir(bookingsTable.startTime)]
309	    : [dir(bookingsTable.date), dir(bookingsTable.startTime), dir(bookingsTable.id)];
310	
311	  const whereExpr = and(...filters);
312	
313	  const [rows, totalRow] = await Promise.all([
314	    db.select({
315	      booking: bookingsTable,
316	      courtName: courtsTable.name,
317	      facilityName: facilitiesTable.name,
318	      serviceName: coachServicesTable.name,
319	      serviceDurationMin: coachServicesTable.durationMin,
320	    })
321	      .from(bookingsTable)
322	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
323	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
324	      .leftJoin(coachServicesTable, eq(bookingsTable.coachServiceId, coachServicesTable.id))
325	      .where(whereExpr)
326	      .orderBy(...orderByColumns)
327	      .limit(q.limit)
328	      .offset(q.offset),
329	
330	    db.select({ count: sql<number>`COUNT(*)::int` })
331	      .from(bookingsTable)
332	      .where(whereExpr),
333	  ]);
334	
335	  const total = totalRow[0]?.count ?? 0;
336	
337	  res.json({
338	    items: rows.map((r) => {
339	      const totalPriceCents = Math.round(Number(r.booking.totalPrice) * 100);
340	      const durationMin = bookingDurationMin(r.booking.startTime, r.booking.endTime);
341	      const isManual = r.booking.bookerUserId === null && totalPriceCents === 0;
342	      // Refund tracking: bookings.refundAmount is a numeric string in EUR;
343	      // anything > 0 means a refund was issued. We don't surface partial vs
344	      // full here — the caller can compare against totalPriceCents if needed.
345	      const refundCents = Math.round(Number(r.booking.refundAmount ?? 0) * 100);
346	      return {
347	        id: r.booking.id,
348	        date: r.booking.date,
349	        startTime: r.booking.startTime,
350	        endTime: r.booking.endTime,
351	        durationMin,
352	        status: r.booking.status,
353	        courtId: r.booking.courtId,
354	        courtName: r.courtName,
355	        facilityName: r.facilityName,
356	        serviceId: r.booking.coachServiceId,
357	        serviceName: r.serviceName,
358	        customerName: r.booking.customerName,
359	        customerEmail: r.booking.customerEmail,
360	        customerPhone: r.booking.customerPhone,
361	        bookerUserId: r.booking.bookerUserId,
362	        isManual,
